\label{c11}
  The equation $p(x,y,n)=x^{2}-y^{2}-n^{2}$ is partition regular in $\mathbb{Z}[i]\backslash \{0\}$. Equivalently, the system of equations
  \begin{equation} \nonumber
  \begin{split}
          & p_{1}((x_{1},x_{2}),(y_{1},y_{2}),(n_{1},n_{2}))=x_{1}^{2}-x_{2}^{2}-y_{1}^{2}+y_{2}^{2}-n_{1}^{2}+n_{2}^{2};
          \\& p_{2}((x_{1},x_{2}),(y_{1},y_{2}),(n_{1},n_{2}))=x_{1}x_{2}-y_{1}y_{2}-n_{1}n_{2}
   \end{split}
   \end{equation}
is partition regular in $\mathbb{Z}^{2}\backslash \{(0,0)\}$.

 The convolution product of two functions $f,g\colon R_{\tilde{N}}\rightarrow\mathbb{C}$ is defined by
  \begin{equation}\nonumber
  \begin{split}
   f*g(\alpha)=\mathbb{E}_{\beta\in R_{\tilde{N}}}f(\alpha-\beta)g(\beta),
  \end{split}
  \end{equation}
where for any function $f\colon S\rightarrow\mathbb{C}$ on a finite set $S$, we denote $\mathbb{E}_{x\in S}f(x)=\frac{1}{\vert S\vert}\sum_{x\in S}f(x)$.
Here $\vert S\vert$ denotes the cardinality of $S$.

  For any $\alpha=\alpha_{1}+\alpha_{2}i,\beta=\beta_{1}+\beta_{2}i\in R_{\tilde{N}}$, write
  \begin{equation}\nonumber
  \begin{split}
   \alpha\circ_{N}\beta=\frac{1}{\tilde{N}}(\alpha_{1}\beta_{1}+\alpha_{2}\beta_{2}).
  \end{split}
  \end{equation}
  For any function $f\colon R_{\tilde{N}}\rightarrow\mathbb{C}$ and $\bold{\xi}=\xi_{1}+\xi_{2}i\in R_{\tilde{N}}$, we let $\widehat{f}\colon R_{\tilde{N}}\rightarrow\mathbb{C}$ denote the \emph{Fourier transformation} of $f$
  \begin{equation}\nonumber
  \begin{split}
   \widehat{f}(\bold{\xi})=\mathbb{E}_{\alpha\in R_{\tilde{N}}}f(\alpha)e(-\alpha\circ_{N}\bold{\xi})
  \end{split}
  \end{equation}
for all $\bold{\xi}\in R_{\tilde{N}}$, where $e(x)=\exp(2\pi ix)$ for all $x\in\mathbb{R}$.

For $d\geq 1$, we define the \emph{$d$-th Gowers uniformity norm} of $f$ on $R_{\tilde{N}}$ inductively by
  \begin{equation}\nonumber
    \begin{split}
      \Vert f\Vert_{U^{1}(R_{\tilde{N}})}=\Bigl\vert\mathbb{E}_{\alpha\in R_{\tilde{N}}}f(\alpha)\Bigr\vert
    \end{split}
  \end{equation}
and
  \begin{equation}\nonumber
    \begin{split}
      \Vert f\Vert_{U^{d+1}(R_{\tilde{N}})}=\Bigl(\mathbb{E}_{\beta\in R_{\tilde{N}}}\Vert f_{\beta}\cdot\overline{f}\Vert_{_{U^{d}(R_{\tilde{N}})}}^{2^{d}}\Bigr)^{1/2^{d+1}}
    \end{split}
  \end{equation}
for $d\geq 1$, where $\overline{f}$ denotes the conjugate of $f$ and $f_{\beta}(\alpha)=f(\beta+\alpha)$ for all $\alpha\in R_{\tilde{N}}$.

\label{nU3s}($U^{3}$ decomposition theorem).
  For every positive finite measure $\nu$ on the group $\mathcal{M}_{\mathbb{Z}[i]}$, every function $F\colon\mathbb{N}\times\mathbb{N}\times\mathbb{R}^{+}\rightarrow\mathbb{R}^{+}$, every $\epsilon>0$, and every $N\in\mathbb{N}$ sufficiently large depending only on $F$ and $\epsilon$, there exist positive integers $Q=Q(F,N,\epsilon,\nu)$ and $R=R(F,N,\epsilon,\nu)$ bounded by a constant depending only on $F$ and $\epsilon$ such that for every $\chi\in\mathcal{M}_{\mathbb{Z}[i]}$, the function $\chi_{N}\coloneqq\chi\cdot\bold{1}_{R_{N}}$ can be written as
  \begin{equation}\nonumber
   \begin{split}
     \chi_{N}(\alpha)=\chi_{N,s}(\alpha)+\chi_{N,u}(\alpha)+\chi_{N,e}(\alpha)
   \end{split}
  \end{equation}
for all $\alpha\in R_{\tilde{N}}$ such that

  (i) $\chi_{N,s}=\chi_{N}*\phi_{N,1}$ and $\chi_{N,s}+\chi_{N,e}=\chi_{N}*\phi_{N,2}$, where $\phi_{N,1}$ and $\phi_{N,2}$ are kernels of $R_{\tilde{N}}$ that are independent of $\chi$, and the convolution product is defined on $R_{\tilde{N}}$;

  (ii) $\vert\chi_{N,s}(\alpha+Q)-\chi_{N,s}(\alpha)\vert, \vert\chi_{N,s}(\alpha+Qi)-\chi_{N,s}(\alpha)\vert\leq\frac{R}{N}$ for every $\alpha\in R_{\tilde{N}}$;

  (iii) $\Vert\chi_{N,u}\Vert_{U^{3}(R_{\tilde{N}})}\leq\frac{1}{F(Q,R,\epsilon)}$;

  (iv) $\mathbb{E}_{\alpha\in R_{\tilde{N}}}\int_{\mathcal{M}_{\mathbb{Z}[i]}}\vert\chi_{N,e}(\alpha)\vert d\nu(\chi)\leq\epsilon$.

\label{c1}(Partition regularity theorem for a special class of equations on $\mathbb{Z}[i]$).
  Let $p$ be a quadratic equation of the form
    \begin{equation}\nonumber
    \begin{split}
      p(x,y,n)=ax^{2}+by^{2}+cn^{2}+dxy+exn+fyn
    \end{split}
  \end{equation}
  for some $a,b,c,d,e,f\in\mathbb{Z}[i]$. If all of $\sqrt{e^{2}-4ac}, \sqrt{f^{2}-4bc},\sqrt{(e+f)^{2}-4c(a+b+d)}$ belong to $\mathbb{Z}[i]$, then
  $p(x,y,n)$ is partition regular in $\mathbb{Z}[i]$.

 A 4-tuple of Gaussian integers $(\gamma_{1},\gamma_{2},\gamma_{3},\gamma_{4})\in\mathbb{Z}[i]^{4}$ is \emph{admissible} if $\gamma_{1}
eq \gamma_{2}$, $\gamma_{3}
eq \gamma_{4}$ and $\{\gamma_{1},\gamma_{2}\}
eq \{\gamma_{3},\gamma_{4}\}$.

\label{c4}(Multiple recurrence property for multiplicative functions).
  Let $(\gamma_{1},\gamma_{2},\gamma_{3},\gamma_{4})\in\mathbb{Z}[i]^{4}$ be an admissible 4-tuple. Let $\nu$ be a positive finite measure on the group $\mathcal{M}_{\mathbb{Z}[i]}$ such that $\nu(\{\bold{1}\})>0$ and
       $$\int_{\mathcal{M}_{\mathbb{Z}[i]}}\chi(x)\overline{\chi}(y)d\nu(\chi)\geq 0$$ 
for all $x,y\in \mathbb{Z}[i]$. 
 Then there exist $\alpha,\beta\in\mathbb{Z}[i]$ such that
  $(\alpha+\gamma_{1}\beta)(\alpha+\gamma_{2}\beta)$ and $(\alpha+\gamma_{3}\beta)(\alpha+\gamma_{4}\beta)$ are distinct and nonzero, and
    \begin{equation}\nonumber
  \begin{split}
    \int_{\mathcal{M}_{\mathbb{Z}[i]}}{\chi(\alpha+\gamma_{1}\beta)\chi(\alpha+\gamma_{2}\beta)\overline{\chi}(\alpha+\gamma_{3}\beta)
    \overline{\chi}(\alpha+\gamma_{4}\beta)}d\nu(\chi)>0.
  \end{split}
  \end{equation}
  Moreover, if $\gamma_{1},\gamma_{2},\gamma_{3},\gamma_{4}$ are pairwise distinct, we have that
  \begin{equation}\label{temp9}
  \begin{split}
    \liminf_{N\rightarrow\infty}\mathbb{E}_{(\alpha,\beta)\in\Theta_{N}}\int_{\mathcal{M}_{\mathbb{Z}[i]}}{\chi(\alpha+\gamma_{1}\beta)\chi(\alpha+\gamma_{2}\beta)\overline{\chi}(\alpha+\gamma_{3}\beta)
    \overline{\chi}(\alpha+\gamma_{4}\beta)}d\nu(\chi)>0,
  \end{split}
  \end{equation}
  where $\Theta_{N}=\{(\alpha,\beta)\in R_{N}\times  R_{N}\colon \alpha+\gamma_{i}\beta\in R_{N}, i=1,2,3,4\}$.

The proof is similar to Proposition 10.3 and Proposition 10.4 in ~\cite{FH}. We omit the proof but stress the differences. First of all, we need to use Theorem \ref{nU3s} to decompose $\chi_{N}$ into the sum $\chi_{N,s}+\chi_{N,u}+\chi_{N,e}$. Then we can expand the left hand side of (\ref{temp9}) into 81 terms. By a similar argument as Proposition 10.5 in ~\cite{FH}, we have that
   \begin{equation}\nonumber
  \begin{split}
    \liminf_{N\rightarrow\infty}\mathbb{E}_{(\alpha,\beta)\in\Theta_{N}}\int_{\mathcal{M}_{\mathbb{Z}[i]}}{\chi_{N,s}(\alpha+\gamma_{1}\beta)\chi_{N,s}(\alpha+\gamma_{2}\beta)\overline{\chi_{N,s}}(\alpha+\gamma_{3}\beta)
    \overline{\chi_{N,s}}(\alpha+\gamma_{4}\beta)}d\nu(\chi)
  \end{split}
  \end{equation}
is bounded below by a positive number which is independent of $\epsilon$. So
 it suffices to show that all other terms are negligible. A term is obvious $O(\epsilon)$ if it contents the expression $\chi_{N,e}$. It then suffices to show that all terms containing the expression $\chi_{N,u}$ are negligible, which holds immediately if one can show that
      \begin{equation}\label{temp8}
    \begin{split}
      \Bigl\vert\mathbb{E}_{\alpha,\beta\in R_{\tilde{N}}}\bold{1}_{R_{N}}(\beta)\prod_{j=0}^{3}a_{j}(\alpha+\gamma_{j}\beta)\Bigr\vert
      \leq C\min_{1\leq j\leq 4}(\Vert a_{j}\Vert_{U^{3}(R_{\tilde{N}})})^{1/3}+\frac{10}{\tilde{N}}
    \end{split}
  \end{equation}
for all functions $a_{1},\dots,a_{4}$ on $R_{\tilde{N}}$ with $\Vert a_{j}\Vert_{L^{\infty}(R_{\tilde{N}})}\leq 1$ for $j=1,\dots,4$, where $C>0$ depends only on $\gamma_{1},\dots,\gamma_{4}$ (the exponent on the right hand side of (\ref{temp8}) is $\frac{1}{2}$ for the 1-dimensional case and is $\frac{1}{3}$ for the 2-dimensional case).

The sequence $\{\Phi_{N}\}_{N\in\mathbb{N}}$ of finite subsets of $\mathbb{Z}[i]$ is a \emph{multiplicative F${\o}$lner sequence} if for every $\alpha\in\mathbb{Z}[i]$,
\begin{equation}\nonumber
\begin{split}
  \lim_{N\rightarrow\infty}\frac{\vert \alpha\Phi_{N}\triangle\Phi_{N}\vert}{\vert \Phi_{N}\vert}=0,
\end{split}
\end{equation}
where $\alpha\Phi_{N}=\{\alpha x\colon x\in\Phi_{N}\}$.

The \emph{multiplicative density} $d_{mult}(E)$ of a subset $E$ of $\mathbb{Z}[i]$ (with respect to the multiplicative F${\o}$lner sequence $\{\Phi_{N}\}_{N\in\mathbb{N}}$) is defined to be
\begin{equation}\nonumber
\begin{split}
  d_{mult}(E)=\limsup_{N\rightarrow\infty}\frac{\vert E\cap\Phi_{N}\vert}{\vert \Phi_{N}\vert}.
\end{split}
\end{equation}

\label{FC}(Furstenberg correspondence principle).
  Let $E$ be a subset of $\mathbb{Z}[i]$. Then there exist an action by dilation $\{T_{\alpha}\}_{\alpha\in\mathbb{Z}[i]}$ on a probability space $(X,\mathcal{B},\mu)$ and a set $A\in\mathcal{B}$ with $\mu(A)=d_{mult}(E)$ such that for all $k\in\mathbb{N}$ and for all $\alpha_{1},\dots,\alpha_{k}\in\mathbb{Z}[i]$, we have
    \begin{equation}\nonumber
  \begin{split}
    d_{mult}(\alpha_{1}^{-1}E\cap\dots\cap \alpha_{k}^{-1}E)\geq\mu(T_{\alpha_{1}}^{-1}A\cap\dots\cap T_{\alpha_{k}}^{-1}A),
  \end{split}
  \end{equation}
  where $\alpha^{-1}E=\{x\in\mathbb{Z}[i]\colon \alpha x\in E\}$.

For every $f\in L^{2}(\mu)$, by the spectral theorem, there exists a positive finite measure $\nu$ (called the \emph{spectral measure  of $f$}) on the group of
multiplicative functions $\mathcal{M}_{\mathbb{Z}[i]}$ such that for all $\alpha,\beta\in\mathbb{Z}[i]$,
\begin{equation}\nonumber
  \begin{split}
    \int_{X}{T_{\alpha}f\cdot T_{\beta}\overline{f}}d\mu=\int_{X}{T_{\alpha/\beta}f\cdot \overline{f}}d\mu=\int_{\mathcal{M}_{\mathbb{Z}[i]}}{\chi(\alpha/\beta)}d\nu(\chi)
    =\int_{\mathcal{M}_{\mathbb{Z}[i]}}{\chi(\alpha)\overline{\chi}(\beta)}d\nu(\chi).
  \end{split}
  \end{equation}

\label{c3}
  Let $(\gamma_{1},\gamma_{2},\gamma_{3},\gamma_{4})\in\mathbb{Z}[i]^{4}$ be an admissible 4-tuple. Let $\{T_{\alpha}\}_{\alpha\in\mathbb{Z}[i]}$ be an action by dilation on a probability space $(X,\mathcal{B},\mu)$. Then for every $A\in\mathcal{B}$ with $\mu(A)>0$, there exist $\alpha,\beta\in\mathbb{Z}[i]$ such that $(\alpha+\gamma_{1}\beta)(\alpha+\gamma_{2}\beta)$ and $(\alpha+\gamma_{3}\beta)(\alpha+\gamma_{4}\beta)$ are distinct and non-zero, and
    \begin{equation}\nonumber
  \begin{split}
    \mu(T_{(\alpha+\gamma_{1}\beta)(\alpha+\gamma_{2}\beta)}^{-1}A\cap T_{(\alpha+\gamma_{3}\beta)(\alpha+\gamma_{4}\beta)}^{-1}A)>0.
  \end{split}
  \end{equation}
  Moreover, if $\gamma_{1},\gamma_{2},\gamma_{3},\gamma_{4}$ are pairwise distinct, we have that
  \begin{equation}\nonumber
  \begin{split}
    \liminf_{N\rightarrow\infty}\mathbb{E}_{(\alpha,\beta)\in\Theta_{N}}\mu(T_{(\alpha+\gamma_{1}\beta)(\alpha+\gamma_{2}\beta)}^{-1}A\cap T_{(\alpha+\gamma_{3}\beta)(\alpha+\gamma_{4}\beta)}^{-1}A)>0,
  \end{split}
  \end{equation}
  where $\Theta_{N}=\{(\alpha,\beta)\in R_{N}\times  R_{N}\colon \alpha+\gamma_{i}\beta\in R_{N}, i=1,2,3\}$.

 For any partition of $\mathbb{Z}[i]$ into finitely many cells, one of the cells $E$ has positive multiplicative density. Let $A$ be the set in Theorem \ref{FC} corresponding to $E$.
By Corollary \ref{c3},
there exist $\alpha,\beta\in\mathbb{Z}[i]$ such that $(\alpha+\gamma_{1}\beta)(\alpha+\gamma_{2}\beta)$ and $(\alpha+\gamma_{3}\beta)(\alpha+\gamma_{4}\beta)$ are distinct and nonzero, and
\begin{equation}\nonumber
  \begin{split}
    \mu(T_{\gamma_{0}(\alpha+\gamma_{1}\beta)(\alpha+\gamma_{2}\beta)}^{-1}A\cap T_{\gamma_{0}(\alpha+\gamma_{3}\beta)(\alpha+\gamma_{4}\beta)}^{-1}A)=\mu(T_{(\alpha+\gamma_{1}\beta)(\alpha+\gamma_{2}\beta)}^{-1}A\cap T_{(\alpha+\gamma_{3}\beta)(\alpha+\gamma_{4}\beta)}^{-1}A)>0.
  \end{split}
  \end{equation}
  So $d_{mult}(\gamma_{0}^{-1}(\alpha+\gamma_{1}\beta)^{-1}(\alpha+\gamma_{2}\beta)^{-1}E\cap\gamma_{0}^{-1}(\alpha+\gamma_{3}\beta)^{-1}(\alpha+\gamma_{4}\beta)^{-1}E)>0$. Thus there exists $\gamma\in\mathbb{Z}[i]$ such that
  $\gamma\gamma_{0}(\alpha+\gamma_{1}\beta)(\alpha+\gamma_{2}\beta)$ and $\gamma\gamma_{0}(\alpha+\gamma_{3}\beta)(\alpha+\gamma_{4}\beta)$ are distinct and nonzero, and they both belong to $E$.

\label{TK} Let $x\in\mathbb{N}$ be sufficiently large with respect to $\mathcal{P}$. Then
\begin{equation}\label{TK2}
  \begin{split}
    \frac{1}{s(x)}\sum_{\mathcal{N}(\alpha)\leq x}\vert\omega_{\mathcal{P}}(\alpha)-A_{\mathcal{P}}\vert\leq C A_{\mathcal{P}}^{1/2}
  \end{split}
\end{equation}
for some universal constant $C$.

\label{TK3} Let $x\in\mathbb{N}$ be sufficiently large with respect to $\mathcal{P}$. Then
\begin{equation}\nonumber
  \begin{split}
    \frac{1}{x^{2}}\sum_{\alpha\in R_{x}}\vert\omega_{\mathcal{P}}(\alpha)-A_{\mathcal{P}}\vert\leq 8 C A_{\mathcal{P}}^{1/2}
  \end{split}
\end{equation}
for some universal constant $C$.

\label{cls}
  The prime elements $p$ of $\mathbb{Z}[i]$, up to a multiple of unit elements, is of one of the following three forms:

  (i) $p=1+i$;

  (ii) $p=a+bi, a^{2}+b^{2}=p_{0}, p_{0}\equiv 1 \mod 4$;

  (iii) $p=p_{0}, p_{0}\equiv 3 \mod 4$.

  Here $p_{0}$ is a prime in $\mathbb{Z}$.

\label{katai}(Katai's Lemma).
  For every $\epsilon>0$ and $K_{0}\in\mathbb{N}$, there exist $\delta=\delta(\epsilon,K_{0})>0$ and $K=K(\epsilon,K_{0})>K_{0}$ such that the following holds: If $N$ is sufficiently large with respect to $K$ and $f\colon R_{N}\rightarrow\mathbb{C}$ is a function with $\vert f\vert\leq 1$, and
    \begin{equation}\label{kt4}
  \begin{split}
    \max_{p,q\in\mathbb{P}[i], K_{0}<\mathcal{N}(p)<\mathcal{N}(q)<K}\frac{1}{\vert R_{N}\vert}\Bigl\vert\sum_{\alpha\in R_{N}/p\cap R_{N}/q}f(p\alpha)\overline{f}(q\alpha)\Bigr\vert<\delta,
  \end{split}
\end{equation}
then
    \begin{equation}\nonumber
  \begin{split}
    \sup_{\chi\in\mathcal{M}_{\mathbb{Z}[i]}}\Bigl\vert\mathbb{E}_{\alpha\in R_{N}}\chi(\alpha)f(\alpha)\Bigr\vert<\epsilon,
  \end{split}
\end{equation}
where $R_{N}/p=\{\alpha\in\mathbb{Z}[i]\colon p\alpha\in R_{N}\}$.

 Let $\mathcal{P}=\{p\in\mathbb{P}[i]\colon K_{0}<\mathcal{N}(p)<K\}$. Fix $\chi\in\mathcal{M}_{\mathbb{Z}[i]}$. Let
\begin{equation}\nonumber
  \begin{split}
    S(N)=\sum_{\alpha\in R_{N}}\chi(\alpha)f(\alpha),
  \end{split}
\end{equation}

\begin{equation}\nonumber
  \begin{split}
    H(N)=\sum_{\alpha\in R_{N}}\chi(\alpha)f(\alpha)\omega_{\mathcal{P}}(\alpha).
  \end{split}
\end{equation}
 By Corollary \ref{TK3},
\begin{equation}\label{kt1}
  \begin{split}
    \vert H(N)-A_{\mathcal{P}}S(N)\vert\leq 8CN^{2}A_{\mathcal{P}}^{1/2}
  \end{split}
\end{equation}
for some universal constant $C$.
Notice that
\begin{equation}\nonumber
  \begin{split}
    H(N)=\sum_{p\in\mathcal{P}}\sum_{\beta\in R_{N}/p}\chi(p\beta)f(p\beta)=\sum_{\beta\in R_{N}}\chi(\beta)\Sigma_{\beta},
  \end{split}
\end{equation}
where $\Sigma_{\beta}=\sum_{p\in\mathcal{P}\cap R_{N}/\beta}\chi(p)f(p\beta)$. By the Cauchy-Schwartz Inequality,
\begin{equation}\label{kt2}
  \begin{split}
    \vert H(N)\vert^{2}\leq\Bigl(\sum_{\mathcal{N}(\beta)\leq 2N}\vert\chi(\beta)\vert^{2}\Bigr)\Bigl(\sum_{\mathcal{N}(\beta)\leq 2N}\vert\Sigma_{\beta}\vert^{2}\Bigr)\leq 4CN^{2}\sum_{\mathcal{N}(\beta)\leq 2N}\vert\Sigma_{\beta}\vert^{2}
  \end{split}
\end{equation}
since $R_{N}\subset \{\beta\colon N(\beta)\leq 2N\}$.
It is easy to deduce that $\sum_{p\in\mathcal{P}}\vert R_{N}/p\vert\leq C'RN^{2}A_{\mathcal{P}}$ for some universal constant $C'>0$. Thus

\begin{equation}\label{kt3}
  \begin{split}
    &\qquad\sum_{\mathcal{N}(\beta)\leq 2N}\vert\Sigma_{\beta}\vert^{2}=\sum_{\mathcal{N}(\beta)\leq 2N}\sum_{p,q\in\mathcal{P}\cap R_{N}/\beta}\chi(p)\overline{\chi}(q)f(p\beta)\overline{f}(q\beta)
    \\&\leq C'RN^{2}A_{\mathcal{P}}+\sum_{p,q\in\mathcal{P},\mathcal{N}(p)\neq \mathcal{N}(q)}\Bigl\vert \sum_{\beta\in R_{N}/p\cap R_{N}/q}f(p\beta)\overline{f}(q\beta)\Bigr\vert,
  \end{split}
\end{equation}
where we used Proposition \ref{ne}. Combining (\ref{kt1}),(\ref{kt2}) and (\ref{kt3}), we obtain

\begin{equation}\nonumber
  \begin{split}
    \frac{A_{\mathcal{P}}^{2}\vert S(N)\vert^{2}}{N^{4}}\leq C''\Bigl(1+A_{\mathcal{P}}+\sum_{p,q\in\mathcal{P},\mathcal{N}(p)\neq \mathcal{N}(q)}\frac{1}{N^{2}}\Bigl\vert \sum_{\beta\in R_{N}/p\cap R_{N}/q}f(p\beta)\overline{f}(q\beta)\Bigr\vert\Bigr)
  \end{split}
\end{equation}
for some universal constant $C''>0$. Since $\sum_{p\in\mathbb{P}[i]}\frac{1}{\mathcal{N}(p)^{2}}=\infty$, the lemma follows by picking $K$ first and then $\delta$ appropriately.

  Let $\delta=\delta(\epsilon,1)$ and $K=K(\epsilon,1)$ be given by Lemma \ref{katai}. Let
    \begin{equation}\nonumber
  \begin{split}
   Q=\prod_{p,q\in\mathbb{P}[i],\mathcal{N}(p)<\mathcal{N}(q)<K}\mathcal{N}(p-q)^{2}\in\mathbb{N}.
  \end{split}
\end{equation}
Suppose that $N>K$. Let $q,p\in\mathbb{P}[i]$ with $\mathcal{N}(p)<\mathcal{N}(q)<K$ and let $\xi\in R_{\tilde{N}}$. Denote $p=p_{1}+p_{2}i,q=q_{1}+q_{2}i$. Let $\bold{v}=(p_{1}-q_{1},p_{2}-q_{2}), \bold{w}=(q_{2}-p_{2},p_{1}-q_{1})$. Let $f\colon R_{\tilde{N}}\rightarrow\mathbb{C}, f(\alpha)=e(-\alpha\circ_{N}\bold{\xi})$.

  For $i\in\mathbb{Z}$, denote $U_{j}=\{\alpha\in R_{N}/p\cap R_{N}/q\colon Im(\alpha)=j\}$. Then $ R_{N}/p\cap R_{N}/q=\bigcup_{j=-2N}^{2N}U_{j}$. By the convexity of $ R_{N}/p\cap R_{N}/q$, each $U_{j}$ can be written as $U_{j}=\{x+ji\colon a_{j}\leq x\leq b_{j}\}$ for some $a_{j}, b_{j}\in\mathbb{Z}$. We have
  \begin{equation}\nonumber
  \begin{split}
   &\qquad\frac{1}{\tilde{N}^{2}}\Bigl\vert\sum_{\alpha\in R_{N}/p\cap R_{N}/q}f(p\alpha)\overline{f}(q\alpha)\Bigr\vert
   \leq\frac{1}{{\tilde{N}^{2}}}\sum_{j=-2N}^{2N}\Bigl\vert\sum_{\alpha\in U_{j}}f(p\alpha)\overline{f}(q\alpha)\Bigr\vert
   \\&=\frac{1}{{\tilde{N}^{2}}}\sum_{j=-2N}^{2N}\Bigl\vert\sum_{x=a_{j}}^{b_{j}}e(-x\bold{v}\circ_{N}\bold{\xi})e(-j\bold{w}\circ_{N}\bold{\xi}) \Bigr\vert
   \leq\frac{1}{{\tilde{N}^{2}}}\sum_{j=-2N}^{2N}
   \frac{2}{\Vert \bold{v}\circ_{N}\bold{\xi}\Vert}\leq\frac{C}{N\Vert\bold{v}\circ_{N}\bold{\xi}\Vert}
  \end{split}
\end{equation}
for some universal constant $C$.
On the other hand, writing $V_{j}=\{\alpha\in R_{N}/p\cap R_{N}/q\colon Re(\alpha)=i\}$, then a similar argument shows that 
$$\frac{1}{\tilde{N}^{2}}\Bigl\vert\sum_{\alpha\in R_{N}/p\cap R_{N}/q}f(p\alpha)\overline{f}(q\alpha)\Bigr\vert\leq\frac{C}{N\Vert\bold{w}\circ_{N}\bold{\xi}\Vert}.$$

If $\vert\widehat{\chi_{N}}(\xi)\vert\geq\epsilon$, by Lemma \ref{katai}, there exist $p,q\in\mathbb{P}[i], \mathcal{N}(p)<\mathcal{N}(q)<K$ such that $\frac{1}{\tilde{N}^{2}}\Bigl\vert\sum_{\alpha\in R_{N}/p\cap R_{N}/q}f(p\alpha)\overline{f}(q\alpha)\Bigr\vert\geq \delta$. Thus $\max\{\Vert\bold{v}\circ_{N}\bold{\xi}\Vert,\Vert\bold{w}\circ_{N}\bold{\xi}\Vert\}\leq \frac{C'}{N\delta}$
for some universal constant $C'$.
Suppose
  \begin{equation}\nonumber
  \begin{split}
   &\bold{v}\circ_{N}\bold{\xi}=\frac{1}{\tilde{N}}((p_{1}-q_{1})\xi_{1}+(p_{2}-q_{2})\xi_{2})=a_{1}\pm\Vert\bold{v}\circ_{N}\bold{\xi}\Vert;
   \\&\bold{w}\circ_{N}\bold{\xi}=\frac{1}{\tilde{N}}((q_{2}-p_{2})\xi_{1}+(p_{1}-q_{1})\xi_{2})=a_{2}\pm\Vert\bold{w}\circ_{N}\bold{\xi}\Vert
  \end{split}
\end{equation}
for some $a_{1},a_{2}\in\mathbb{Z}$. Then
$\xi_{1}/\tilde{N}=(n_{1}+\delta_{1})/\Delta, \xi_{2}/\tilde{N}=(n_{2}+\delta_{2})/\Delta$,
where $\Delta=(p_{1}-q_{1})^{2}+(p_{2}-q_{2})^{2}\neq 0, n_{1},n_{2}\in\mathbb{Z}, \vert\delta_{1}\vert, \vert\delta_{2}\vert\leq\frac{KC''}{N\delta}$ for some universal constant $C''$. Since
$\Delta$ divides $Q$, we get $\Vert Q\xi_{i}/\tilde{N}\Vert=\Vert Q\delta_{i}/\tilde{N}\Vert\leq\frac{KC''}{N\delta}$ for $i=1,2$. The corollary follows by taking $V=\lceil\frac{KC''}{\delta}\rceil$ (recall that $\lceil x\rceil$ is the smallest integer which is not smaller than $x$).

  We show that $\phi_{N,\epsilon}$ defined in (\ref{phi}) satisfies all the requirements. Suppose $0<\epsilon'\leq\epsilon$. Since $Q(\epsilon')\geq Q(\epsilon), V(\epsilon')\geq V(\epsilon)$ and $Q(\epsilon')$ is a multiple of $Q(\epsilon)$, we have $\Xi_{N,\epsilon}\subset\Xi_{N,\epsilon'}$ and $\widehat{\phi_{N,\epsilon'}}(\bold{\xi})\geq\widehat{\phi_{N,\epsilon}}(\bold{\xi})$ for every $\bold{\xi}\in R_{\tilde{N}}$.

  For every $\chi\in\mathcal{M}_{\mathbb{Z}[i]},\bold{\xi}=\xi_{1}+\xi_{2}i\in R_{\tilde{N}}$, if $\vert\widehat{\chi_{N}}(\bold{\xi})\vert\geq\epsilon^{2}$, then by the definition of $Q, \Vert\frac{Q\xi_{i}}{\tilde{N}}\Vert\leq QV/\tilde{N}, i=1,2$. Then $\widehat{\phi_{N,\epsilon}}(\bold{\xi})\geq(1-\epsilon^{4}/2)^{2}\geq 1-\epsilon^{4}$. So
  $\vert\widehat{\chi_{N}}(\bold{\xi})-\widehat{\phi_{N,\epsilon}*\chi_{N}}(\bold{\xi})\vert\leq\epsilon^{4}\leq\epsilon^{2}$. The same estimate also holds if $\vert\widehat{\chi_{N}}(\bold{\xi})\vert\leq\epsilon^{2}$. Thus by identity (\ref{F}), we have
    \begin{equation}\nonumber
  \begin{split}
  &\qquad \Vert\chi_{N,u}\Vert_{U^{2}(R_{\tilde{N}})}^{4}=\sum_{\bold{\xi}\in R_{\tilde{N}}}\vert\widehat{\chi_{N}}(\bold{\xi})-\widehat{\phi_{N,\epsilon}*\chi_{N}}(\bold{\xi})\vert^{4}\leq\epsilon^{4}\sum_{\bold{\xi}\in R_{\tilde{N}}}\vert\widehat{\chi_{N}}(\bold{\xi})-\widehat{\phi_{N,\epsilon}*\chi_{N}}(\bold{\xi})\vert^{2}
  \\&\leq\sum_{\bold{\xi}\in R_{\tilde{N}}}\vert\widehat{\chi_{N}}(\bold{\xi})\vert^{2}\leq\epsilon^{4},
  \end{split}
\end{equation}
where the last estimate follows from Parseval's identity. This proves (ii).

Lastly, using Fourier inversion formula and the estimate $\vert e(x)-1\vert\leq 2\pi\Vert x\Vert$, we get
    \begin{equation}\nonumber
  \begin{split}
  &\vert\chi_{N,s}(\alpha+Q)-\chi_{N,s}(\alpha)\vert\leq\sum_{\bold{\xi}=\xi_{1}+\xi_{2}i\in R_{\tilde{N}}}\vert\widehat{\phi_{N,\epsilon}}(\bold{\xi})\vert\cdot 2\pi\Bigl\Vert\frac{Q\xi_{1}}{\tilde{N}}\Bigr\Vert
  \leq\vert\Xi_{N,\epsilon}\vert\cdot\frac{4\pi QV\lceil\epsilon^{-4}\rceil}{\tilde{N}};
  \\& \vert\chi_{N,s}(\alpha+Qi)-\chi_{N,s}(\alpha)\vert\leq\sum_{\bold{\xi}=\xi_{1}+\xi_{2}i\in R_{\tilde{N}}}\vert\widehat{\phi_{N,\epsilon}}(\bold{\xi})\vert\cdot 2\pi\Bigl\Vert\frac{Q\xi_{2}}{\tilde{N}}\Bigr\Vert
  \leq\vert\Xi_{N,\epsilon}\vert\cdot\frac{ 4\pi QV\lceil\epsilon^{-4}\rceil}{\tilde{N}}.
  \end{split}
\end{equation}
Since $\vert\Xi_{N,\epsilon}\vert$ depends only on $\epsilon$, the theorem follows by taking $R=\vert\Xi_{N,\epsilon}\vert\cdot 4\pi QV\lceil\epsilon^{-4}\rceil$.

\label{filt}
Let $G$ be a connected, simply connected Lie group with identity element $e_{G}$ and let $d\in\mathbb{N}$. A \emph{filtration} on $G$ is a finite sequence $G_{\bullet}=\{G_{i}\}_{i=0}^{d+1}$ of closed connected subgroups of $G$ such that
\begin{equation}\nonumber
  \begin{split}
    G=G_{0}=G_{1}\supseteq G_{2}\supseteq\cdots\supseteq G_{d+1}=\{e_{G}\}
  \end{split}
\end{equation}
and $[G_{i},G_{j}]\subseteq G_{i+j}$ for all $i,j\geq 0$, where $[H,H']\coloneqq \{hh'h^{-1}h'^{-1}\colon h\in H, h'\in H'\}$ for all $H,H'<G$. The integer $d$ is called the \emph{order} of $G_{\bullet}$.

Writing $p\colon G\rightarrow X$ for the quotient map, the metric $d_{X}$ is defined by
    \begin{equation}\nonumber
  \begin{split}
  d_{X}(x,y)=\inf_{g,h\in G}\{d_{G}(g,h)\colon p(g)=x, p(h)=y\}.
  \end{split}
\end{equation}

\label{mFo}(Factorization of polynomial sequences, Theorem 10.2 in ~\cite{GT}). Suppose that $X=G/\Gamma$ is a nilmanifold of order 2 with respect to the filtration $G_{\bullet}$. For every $M\in\mathbb{N}$, there exists a finite collection $\mathcal{F}(M)$ of sub-nilmanifolds of $X$, each of the form $X'=G'/\Gamma'$, where $G'$ is a rational subgroup of
$G$ and $\Gamma'=G'\cap\Gamma$, such that the following holds:

For every function $\omega\colon\mathbb{N}\rightarrow\mathbb{R}^{+}$ and every $M_{0}\in\mathbb{N}$, there exists $M_{1}=M_{1}(M_{0},X,\omega)\in\mathbb{N}$ such that for every $N\in\mathbb{N}$ and every polynomial sequence of degree 2  $(g(m,n))_{(m,n)\in[\tilde{N}]\times[\tilde{N}]}$ in $G$ with respect to the filtration $G_{\bullet}$, there exist $M\in\mathbb{N}$ with $M_{0}\leq M\leq M_{1}$, a nilmanifold $X'\in\mathcal{F}(M)$, and a decomposition
\begin{equation}\nonumber
  \begin{split}
  g(m,n)=\epsilon(m,n)g'(m,n)\gamma(m,n), (m,n)\in[\tilde{N}]\times[\tilde{N}],
  \end{split}
\end{equation}
where $\epsilon,g',\gamma$ are polynomials of degree 2 with respect to the filtration $G_{\bullet}$ such that

(i) $\epsilon$ is $(M,(\tilde{N},\tilde{N}))$-smooth;

(ii) $(g'(m,n))_{(m,n)\in[\tilde{N}]\times[\tilde{N}]}$ takes values in $G'$, and the finite sequence $(g'(m,n)\cdot e_{X'})_{(m,n)\in[\tilde{N}]\times[\tilde{N}]}$ is totally $\omega(M)$-equidistributed in $X'$ with the metric $d_{X'}$;

(iii) $\gamma\colon[\tilde{N}]\times[\tilde{N}]\rightarrow G$ is $M$-rational, and $(\gamma(m,n)\cdot e_{X})_{(m,n)\in[\tilde{N}]\times[\tilde{N}]}$ is doubly periodic with periods at most $M$.

\label{mF}(Modified factorization theorem).
  Let $X=G/\Gamma$ be a nilmanifold of order 2 with respect to the filtration $G_{\bullet}$ and with vertical torus of dimension 1. For every $M\in\mathbb{N}$, there exists a finite collection $\mathcal{F}(M)$ of sub-nilmanifolds of $X$, each of the form $X'=G'/\Gamma'$ with filtration $G'_{\bullet}$, where $G'$ is a rational subgroup of $G$ and $\Gamma'=G'\cap\Gamma$, and either

  (i) $G'$ is an abelian rational subgroup of $G$; or

  (ii) $G'$ is a non-abelian rational subgroup of $G$ and $G_{2}'/(G_{2}'\cap\Gamma')$ has dimension 1, such that the following holds:

  For every $\omega\colon\mathbb{N}\rightarrow\mathbb{R}^{+}$ and every $M_{0}\in\mathbb{N}$, there exists $M_{1}=M_{1}(M_{0},X,\omega)\in\mathbb{N}$ such that for every $N\in\mathbb{N}$ and every polynomial $g\colon\mathbb{Z}^{2}\rightarrow G$ of degree 2 with respect to the filtration $G_{\bullet}$, there exist $M\in\mathbb{N}$ with $M_{0}\leq M\leq M_{1}$, a nilmanifold $X'\in\mathcal{F}(M)$, and a decomposition
\begin{equation}\nonumber
  \begin{split}
  g(m,n)=\epsilon(m,n)g'(m,n)\gamma(m,n), (m,n)\in[\tilde{N}]\times[\tilde{N}]
  \end{split}
\end{equation}
such that

(iii) $\epsilon$ is $(M,(\tilde{N},\tilde{N}))$-smooth;

(iv) for any $(m,n)\in[\tilde{N}]\times[\tilde{N}]$,
\begin{equation}\nonumber
  \begin{split}
  g'(m,n)=g_{0}g_{1,1}^{m}g_{1,2}^{n}g_{2,1}^{\binom{m}{2}}g_{2,2}^{mn}g_{2,3}^{\binom{n}{2}},
  \end{split}
\end{equation}
where $g_{0}, g_{1,1}, g_{1,2},g_{2,1},g_{2,2},g_{2,3}\in G'$, and moreover $g_{2,1},g_{2,2},g_{2,3}\in G'_{2}$ in case (ii), and $(g'(m,n)\cdot e_{X'})_{(m,n)\in[\tilde{N}]\times[\tilde{N}]}$ is totally $\omega(M)$-equidistributed in $X'$ with the metric $d_{X'}$;

(v) $\gamma\colon[\tilde{N}]\times[\tilde{N}]\rightarrow G$ is $M$-rational, and $(\gamma(m,n))_{(m,n)\in[\tilde{N}]\times[\tilde{N}]}$ is doubly periodic with periods at most $M$.

  Suppose $g\colon\mathbb{Z}^{t}\rightarrow\mathbb{R}/\mathbb{Z}$ is a polynomial map with Taylor expansion
  \begin{equation}\nonumber
  \begin{split}
  g(\vec{n})=\sum_{\vec{j}}\binom{\vec{n}}{\vec{j}}a_{\vec{j}},
  \end{split}
\end{equation}
where $a_{\vec{j}}\in\mathbb{R}/\mathbb{Z}$, and the sum is taken over all $\vec{j}=(j_{1},\dots,j_{t})$ such that $j_{1}+\dots+j_{t}\leq d$ for some $d\in\mathbb{N}$. For any $t$-tuple $\vec{N}=(N_{1},\dots,N_{t})\in\mathbb{N}^{t}$, denote
  \begin{equation}\nonumber
  \begin{split}
  \Vert g\Vert_{C^{\infty}[\vec{N}]}=\sup_{\vec{j}\neq\vec{0}}\vec{N}^{\vec{j}}\Vert a_{\vec{j}}\Vert_{\mathbb{R}/\mathbb{Z}},
  \end{split}
\end{equation}
where $\vec{N}^{\vec{j}}=N_{1}^{j_{1}}\cdot\ldots\cdot N_{t}^{j_{t}}$.

  Since $\Vert \eta\circ g\Vert_{C^{\infty}[\vec{N}]}\leq D$, we have that
    \begin{equation}\nonumber
  \begin{split}
  \eta(g(m,n))=\sum_{\vec{j}}\binom{(m,n)}{\vec{j}}a_{\vec{j}},
  \end{split}
\end{equation}
where $\Vert a_{\vec{j}}\Vert\leq\frac{D}{N_{1}^{j_{1}}N_{2}^{j_{2}}}$ for all $0< j_{1}+j_{2}\leq d$. Thus
$\vert e(\eta(g(0,0)))-e(\eta(g(m,n)))\vert\leq 1/2$ for $1\leq m\leq cN_{1}/D, 1\leq n\leq cN_{2}/D$, where $c$ is a constant depending only on $d$. Suppose that $N_{1},N_{2}\geq\frac{8D}{c}$. Then
    \begin{equation}\nonumber
  \begin{split}
  \Bigl\vert\mathbb{E}_{m\leq cN_{1}/D, n\leq cN_{2}/D}e(\eta(g(m,n)))\Bigr\vert\geq\frac{1}{2},
  \end{split}
\end{equation}
which inplies that
    \begin{equation}\nonumber
  \begin{split}
  \Bigl\vert\mathbb{E}_{(m,n)\in[\vec{N}]}\bold{1}_{[cN_{1}/D]\times[cN_{2}/D]}(m,n)
    e(\eta(g(m,n)))\Bigr\vert\geq\frac{c^{2}}{2D^{2}}-\frac{c}{D}(\frac{1}{N_{1}}+\frac{1}{N_{2}})
\geq\frac{c^{2}}{4D^{2}}.
  \end{split}
\end{equation}

 Since $\Vert\eta\Vert\leq D$, the function $x\rightarrow e(\eta(x))$ defined on $X$ is Lipschitz with constant at most $C'D$ for some $C'=C'(X,d)$, and has integral 0 since $\eta$ is non-trivial. Therefore, the sequence $(g(\vec{n})\cdot e_{X})_{\vec{n}\in[\vec{N}]}$ is not totally $CD^{-3}$-equidistributed with $C=c^{2}/4C'$.

\label{est2}(Correlation property for abelian case). Let $X=\mathbb{T}^{s}$ for some $s\in\mathbb{N}$.
  For any $\kappa>0$, there exist $\sigma=\sigma(s,\kappa)>0,N_{0}=N_{0}(s,\kappa)\in\mathbb{N}$ such that for every $N\geq N_{0}$ and every totally $\sigma$-equidistributed degree 2 polynomial $(g(m,n))_{(m,n)\in[\tilde{N}]\times[\tilde{N}]}$ in $X$ of the form
  \begin{equation}\nonumber
  \begin{split}
    g(m,n)=\bold{\alpha}_{0}+\bold{\alpha}_{1}m+\bold{\alpha}_{2}n+\bold{\beta}_{1}\binom{m}{2}+\bold{\beta}_{2}mn+\bold{\beta}_{3}\binom{n}{2},
  \end{split}
  \end{equation}
we have that
  \begin{equation}\nonumber
  \begin{split}
    \sup_{\beta,\chi,\Phi,P}\Bigl\vert\mathbb{E}_{\alpha\in R_{\tilde{N}}}\bold{1}_{P}(\alpha)\chi(\alpha)\Phi(g'(\beta+\alpha)\cdot e_{X})\Bigr\vert<\kappa,
  \end{split}
  \end{equation}
  where $g'\colon R_{\tilde{N}}\rightarrow G, g'(a+bi)=g(a,b)$, and the sup is taken over all $\beta\in R_{\tilde{N}}, \chi\in\mathcal{M}_{\mathbb{Z}[i]}, \Phi\in Lip(X)$ with $\Vert\Phi\Vert_{Lip(X)}\leq 1$ and $\int\Phi dm_{X}=0$, and all $P=\{a+bi\colon a\in P_{1}, b\in P_{2}\}$, where $P_{i}$ is an arithmetic progression in $[\tilde{N}]$ for $i=1,2$.

  In this proof, $C_{1},C_{2},\dots$ are constants depending only on $s$ and $\kappa$.

 Suppose that
    \begin{equation}\nonumber
  \begin{split}
    \Bigl\vert\mathbb{E}_{\alpha\in R_{\tilde{N}}}\bold{1}_{P}(\alpha)\chi(\alpha)\Phi(g'(\beta+\alpha)\cdot e_{X})\Bigr\vert\geq\kappa
  \end{split}
  \end{equation}
  for some $\beta=b_{1}+b_{2}i\in R_{\tilde{N}}, \chi\in\mathcal{M}_{\mathbb{Z}[i]}, \Phi\in Lip(X)$ with $\Vert\Phi\Vert_{Lip(X)}\leq 1$ and $\int\Phi dm_{X}=0$, and some $P=\{a+bi\colon a\in P_{1}, b\in P_{2}\}$, where $P_{i}$ is an arithmetic progression in $[\tilde{N}]$ for $i=1,2$.  Without loss of generality, we assume $\Vert\Phi\Vert_{\mathcal{C}^{2s}(X)}\leq 1$.
Indeed,
there exists a function $\Phi'$ with $\Vert\Phi-\Phi'\Vert_{\infty}\leq \kappa/2$ and 
$\Vert\Phi'\Vert_{\mathcal{C}^{2s}(X)}$ is bounded by a constant depending only on $s$ and $\kappa$.
 Then
 \begin{equation}\nonumber
  \begin{split}
    &\kappa\leq\Bigl\vert\mathbb{E}_{\alpha\in R_{\tilde{N}}}\bold{1}_{P}(\alpha)\chi(\alpha)\Phi(g'(\beta+\alpha)\cdot e_{X})\Bigr\vert
    =\Bigl\vert\sum_{\bold{k}\in\mathbb{Z}^{s}}\widehat{\Phi}(\bold{k})\mathbb{E}_{\alpha\in R_{\tilde{N}}}\bold{1}_{P}(\alpha)\chi(\alpha)e(\bold{k}\cdot g'(\beta+\alpha))\Bigr\vert
    \\&\leq\sum_{\bold{k}\in\mathbb{Z}^{s}\backslash{\{\bold{0}\}}}\frac{C_{0}}{1+\Vert\bold{k}\Vert^{2s}}\Bigl\vert\mathbb{E}_{\alpha\in R_{\tilde{N}}}\bold{1}_{P}(\alpha)\chi(\alpha)e(\bold{k}\cdot g'(\beta+\alpha))\Bigr\vert
  \end{split}
  \end{equation}
  for some constant $C_{0}=C_{0}(s)$.
   So there exist $C_{1}>0, \theta=\theta(s,\kappa)>0,$ and $\bold{k}\in\mathbb{Z}^{s}\backslash{\{\bold{0}\}}$ such that $\Vert \bold{k}\Vert\leq C_{1}$ and
  \begin{equation}\nonumber
  \begin{split}
    \Bigl\vert\mathbb{E}_{\alpha\in R_{\tilde{N}}}\bold{1}_{P}(\alpha)\chi(\alpha)e(\bold{k}\cdot g'(\beta+\alpha))\Bigr\vert\geq\theta.
  \end{split}
  \end{equation}
  Let $\delta=\delta(\theta,1),K=K(\theta,1)$ be the constants that appear in Lemma \ref{katai}. Then there exist $p=p_{1}+p_{2}i,q=q_{1}+q_{2}i\in\mathbb{P}[i], \mathcal{N}(p)<\mathcal{N}(q)\leq K$ such that
   \begin{equation}\nonumber
  \begin{split}
    \frac{1}{N^{2}}\Bigl\vert\sum_{\alpha\in R_{\tilde{N}}/p\cap R_{\tilde{N}}/q}\bold{1}_{P}(p\alpha)\bold{1}_{P}(q\alpha)e(\bold{k}\cdot (g'(\beta+p\alpha)-g'(\beta+q\alpha)))\Bigr\vert\geq\delta.
  \end{split}
\end{equation}

Let $S=R_{\tilde{N}}/p\cap R_{\tilde{N}}/q$. For $j\in\mathbb{Z}$, set $V_{j}=\{\alpha\in S\colon Im(\alpha)=j\}$. Then $S=\bigcup_{j=-2N}^{2N}V_{j}$ and one can verify that $V_{j}=\{a+ji\colon a\in Q_{j}\}$ for some arithmetic progression $Q_{j}$ in $[\tilde{N}]$. So there exists $j\in\mathbb{Z}$ with $-2N\leq j\leq 2N$ such that
 \begin{equation}\nonumber
  \begin{split}
    \frac{1}{N}\Bigl\vert\sum_{\alpha\in V_{j}}e(\bold{k}\cdot (g'(\beta+p\alpha)-g'(\beta+q\alpha)))\Bigr\vert\geq\delta/5.
  \end{split}
\end{equation}
Write
 \begin{equation}\nonumber
  \begin{split}
    h(a)=\bold{k}\cdot\Bigl(g(b_{1}-p_{2}j+p_{1}a,b_{2}+p_{1}j+p_{2}a)-g(b_{1}-q_{2}j+q_{1}a,b_{2}+q_{1}j+q_{2}a)\Bigr).
  \end{split}
\end{equation}
Then the sequence $(h(a))_{a\in[N]}$ is not totally $\delta/5$-equidistributed in the circle. By the abelian version of Theorem \ref{Lei}, there exists $0<\ell\leq D=D(\delta/5)$ such that 
 \begin{equation}\label{tempr1}
  \begin{split}
    \Vert \ell h\Vert_{C^{\infty}[N]}\leq D.
  \end{split}
\end{equation}


Write $\alpha'_{i}=\bold{k}\cdot\bold{\alpha}_{i}, i=0,1,2, \beta'_{i}=\bold{k}\cdot\bold{\beta}_{i}, i=1,2,3$. Let $A=p_{1}^{2}-q_{1}^{2}, B=2p_{1}p_{2}-2q_{1}q_{2}, C=p_{2}^{2}-q_{2}^{2}$. One can calculate that
 \begin{equation}\nonumber
  \begin{split}
    h(a)=\Bigl(\beta'_{1}A+\beta'_{2}B+\beta'_{3}C\binom{a}{2}+(w+\alpha'_{1}(p_{1}-q_{1})+\alpha'_{2}(p_{2}-q_{2})\Bigr) a+r
  \end{split}
\end{equation}
for some $r\in\mathbb{R}/\mathbb{Z}$ independent of $a$, where
 \begin{equation}\nonumber
  \begin{split}
    &w=\beta'_{1}\Bigl(\bigl(\binom{p_{1}}{2}-\binom{q_{1}}{2}\bigr)+b_{1}(p_{1}-q_{1})-j(p_{1}p_{2}-q_{1}q_{2})\Bigr)
    \\&\qquad+\beta'_{2}\Bigl( j(p_{1}^{2}-p_{2}^{2}-q_{1}^{2}+q_{2}^{2})+b_{2}(p_{1}-q_{1})+b_{1}(p_{2}-q_{2})+(p_{1}p_{2}-q_{1}q_{2})\Bigr)
    \\&\qquad+\beta'_{3}\Bigl(\bigl(\binom{p_{2}}{2}-\binom{q_{2}}{2}\bigr)+b_{2}(p_{2}-q_{2})+j(p_{1}p_{2}-q_{1}q_{2})\Bigr).
  \end{split}
\end{equation}
Thus by (\ref{tempr1}), we have
 \begin{equation}\label{c5}
  \begin{split}
    &\Bigl\Vert\ell(\beta'_{1}A+\beta'_{2}B+\beta'_{3}C)\Bigr\Vert\leq\frac{D}{N^{2}}; \\&\Bigl\Vert\ell(w+\alpha'_{1}(p_{1}-q_{1})+\alpha'_{2}(p_{2}-q_{2}))\Bigr\Vert\leq\frac{D}{N}.
  \end{split}
\end{equation}
The first equation of (\ref{c5}) shows that $\beta'_{1}A+\beta'_{2}B+\beta'_{3}C$ is at a distance $\leq C_{2}/N^{2}$ from a rational number with denominator $\leq C_{3}$.

If we set $U_{j}=\{\alpha\in S\colon Re(\alpha)=j\}$, then $S=\bigcup_{j=-2N}^{2N}U_{j}$ and a similar argument shows that $\beta'_{1}C-\beta'_{2}B+\beta'_{3}A$ is at a distance $\leq C_{2}/N^{2}$ from a rational number with denominator $\leq C_{3}$. Setting $W_{j}=\{\alpha=\alpha_{1}+\alpha_{2}i\in S\colon \alpha_{1}-\alpha_{2}=j\}$, then $S=\bigcup_{j=-4N}^{4N}W_{j}$ and a similar argument shows that $-\beta'_{1}B+\beta'_{2}(A-C)+\beta'_{3}B$ is at a distance $\leq C_{2}/N^{2}$ from a rational number with denominator $\leq C_{3}$. Since $\mathcal{N}(p)\neq \mathcal{N}(q)$, we have that $A+C\neq 0$. Thus
 \begin{equation}\nonumber
\begin{vmatrix}

A & B &  C\\

C & -B & A\\

-B & A-C & B\\

\end{vmatrix}=-(A+C)((A-C)^{2}+2B^{2})\neq 0,
\end{equation}
as $(A-C)^{2}+2B^{2}=0$ if and only if $p=\pm q$. This implies that $\beta'_{i}$ is at a distance $\leq C_{4}/N^{2}$ of a rational number with denominator $\leq C_{5}$ for $i=1,2,3$. Combining the second equation of (\ref{c5}), we get that $\alpha'_{1}(p_{1}-q_{1})+\alpha'_{2}(p_{2}-q_{2})$ is at a distance $\leq C_{8}/N$ from a rational number with denominator $\leq C_{9}$ (here we use the fact that $-4N\leq j,b_{1},b_{2}\leq 4N$). If we consider the set $U_{j}=\{\alpha\in S\colon Re(\alpha)=j\}$, a similar argument shows that $-\alpha'_{1}(p_{2}-q_{2})+\alpha'_{2}(p_{1}-q_{1})$ is at a distance $\leq C_{8}/N$ from a rational number with denominator $\leq C_{9}$. Since
 \begin{equation}\nonumber
\begin{vmatrix}

p_{1}-q_{1} & p_{2}-q_{2}\\

-p_{2}+q_{2} & p_{1}-q_{1}\\

\end{vmatrix}=(p_{1}-q_{1})^{2}+(p_{2}-q_{2})^{2}\neq 0,
\end{equation}
we deduce that $\alpha'_{i}$ is at a distance $\leq C_{10}/N$ from a rational number with denominator $\leq C_{11}$ for $i=1,2$.

Thus we can find some non-zero integer $\ell'$ with $\vert\ell'\vert\leq C_{12}/C_{1}$ such that $\Vert\ell'\beta'_{i}\Vert\leq C_{12}/N^{2}$, for $i=1,2,3$, and $\Vert\ell'\alpha'_{i}\Vert\leq C_{12}/N$, for $i=1,2$. Taking $\bold{k}'=\ell'\bold{k}$, we deduce that $\Vert\bold{k}'\cdot g\Vert_{\mathcal{C}^{\infty}[\tilde{N}]\times[\tilde{N}]}\leq C_{12}$. By Theorem \ref{inv}, $(g(m,n))_{(m,n)\in[\tilde{N}]\times[\tilde{N}]}$ is not totally $\sigma$-equidistributed for some $\sigma>0$ depending only on $s$ and $\kappa$. This finishes the proof.

\label{est1}(Correlation property for non-abelian case).
  For any nilmanifold $X=G/\Gamma$ of order 2 with filtration $G_{\bullet}$ and any $\kappa>0$, there exist $\sigma=\sigma(X,\kappa)>0$ and $N_{0}=N_{0}(X,\kappa)\in\mathbb{N}$ such that for every $N\geq N_{0}$ and every totally $\sigma$-equidistributed degree 2 polynomial $(g(\vec{n}))_{\vec{n}\in[\tilde{N}]\times[\tilde{N}]}$ in $G$ with respect to $G_{\bullet}$, we have that
  \begin{equation}\nonumber
  \begin{split}
    \sup_{\beta,\chi,\Phi,P}\Bigl\vert\mathbb{E}_{\alpha\in R_{\tilde{N}}}\bold{1}_{P}(\alpha)\chi(\alpha)\Phi(g'(\beta+\alpha)\cdot e_{X})\Bigr\vert<\kappa,
  \end{split}
  \end{equation}
  where $g'\colon R_{\tilde{N}}\rightarrow G, g'(a+bi)=g(a,b)$, and the sup is taken over all $\beta\in R_{\tilde{N}}, \chi\in\mathcal{M}_{\mathbb{Z}[i]}, \Phi\in Lip(X)$ with $\Vert\Phi\Vert_{Lip(X)}\leq 1$ and $\int\Phi dm_{X}=0$, and all $P=\{a+bi\colon a\in P_{1}, b\in P_{2}\}$, where $P_{i}$ is an arithmetic progression in $[\tilde{N}]$, for $i=1,2$.

\label{conv2}
Throughout this subsection, $X=G/\Gamma$ is a nilsystem of order 2 with filtration $G_{\bullet}$. We assume without generality that $\dim(G_{2})=1$ (we then show that this assumption can be dropped in Step 1 of the proof of Proposition \ref{est1}). We consider $G_{\bullet}$ as fixed in this subsection. We assume that $G=\mathbb{R}^{s}\times\mathbb{R},\Gamma=\mathbb{Z}^{s}\times\mathbb{Z}$, and under the Mal'cev basis, the group action on $G$ is given by
\begin{equation}\nonumber
    \begin{split}
      (x_{1},\dots,x_{s}; y)\cdot(x'_{1},\dots,x'_{s}; y')=(x_{1}+x'_{1},\dots,x_{s}+x'_{s}; y+y'+\sum_{1\leq j<i\leq s}B_{i,j}x_{i}x'_{j})
    \end{split}
  \end{equation}
  for some $B_{i,j}\in\mathbb{R}, 1\leq j<i\leq s$. So $G_{2}=[G,G]=\{0\}^{s}\times\mathbb{R}$. Let $B^{G}$ denote the $s\times s$ matrix given by $B^{G}_{i,j}=B_{i,j}$
for $i>j$, $B^{G}_{i,j}=-B_{j,i}$ for $i<j$, and $B^{G}_{i,i}=0$ for all $1\leq i\leq s$.
Since $B^{G}$ is skew symmetric, by changing coordinates if necessary, we can always assume that
\begin{equation}\nonumber
B^{G}=\begin{vmatrix}
 B_{0}^{G} & \bold{0} \\
 \bold{0}  & \bold{0} \\
\end{vmatrix}
\end{equation}
for some invertible $s'\times s'$ integer screw symmetric matrix $B_{0}^{G}$, for some $0<s'\leq s$.

For any
 $\bold{x}=(x_{1},\dots,x_{s};x_{s+1})\in G$, we denote $\widehat{\bold{x}}=(x_{1},\dots,x_{s})$
 and $\bold{x}^{\bullet}=(x_{1},\dots,x_{s'})$.

Set $H_{0}=G\times G=\mathbb{R}^{s+1}\times\mathbb{R}^{s+1}, \Gamma_{0}=\Gamma\times\Gamma=\mathbb{Z}^{s+1}\times\mathbb{Z}^{s+1}$. Then $Y_{0}=H_{0}/\Gamma_{0}$ is a nilmanifold of order 2 endowed with the filtration $(H_{0})_{\bullet}=\{G_{i}\times G_{i}\}_{i=0}^{3}$. So $[H_{0},H_{0}]\cong G_{2}\times G_{2}$. Each subgroup $H$ of $H_{0}$ is endowed with the filtration induced by $(H_{0})_{\bullet}$,
   and every subgroup $H$ of $H_{0}$ is identified with a subspace $V(H)$ of $\mathbb{R}^{2s+2}$ under the Mal'cev basis.

We assume that $G=\mathbb{R}^{s}\times\mathbb{R},\Gamma=\mathbb{Z}^{s}\times\mathbb{Z}$, and under the Mal'cev basis, the group action on $G$ is given by
\begin{equation}\nonumber
    \begin{split}
      (x_{1},\dots,x_{s}; y)\cdot(x'_{1},\dots,x'_{s}; y')=(x_{1}+x'_{1},\dots,x_{s}+x'_{s}; y+y'+\sum_{1\leq j<i\leq s}B_{i,j}x_{i}x'_{j})
    \end{split}
  \end{equation}
  for some $B_{i,j}\in\mathbb{R}, 1\leq j<i\leq s$.

\label{dege}
  For any $H<H_{0}$, we have that
\begin{equation}\nonumber
    \begin{split}
      [H,H]=\Bigl\{\bigl((\bold{0};\widehat{\bold{x}}B^{G}\widehat{\bold{y}}^{T}),(\bold{0};\widehat{\bold{z}}B^{G}\widehat{\bold{w}}^{T})\bigl)\colon (\bold{x},\bold{z}),
  (\bold{y},\bold{w})\in H\Bigr\}.
    \end{split}
  \end{equation}

we say that $H$ is of \emph{type 1};
