  \end{split}
  \end{equation}
where $g'_{\beta}(m+ni)=g_{\beta,1,1}^{m}g_{\beta,1,2}^{n}g_{2,1}^{\binom{m}{2}}g_{2,2}^{mn}g_{2,3}^{\binom{n}{2}}$. 
By assumption, we deduce that the sequence $(g'_{\beta}(m+ni))_{(m,n)\in[\tilde{N}]\times[\tilde{N}]}$ is not totally
 $\sigma_{1}$-equidistributed in $X$ for some $\sigma_{1}>0$. 
Let $\eta$ be the horizontal character provided by Theorem \ref{Lei}. Then 
$\eta(g'_{\beta}(\alpha))=\eta(a_{\beta})^{-1}\eta(g'(\alpha+\beta))$.
Applying Lemma \ref{51} with $\phi(\alpha)=\eta(g'(\alpha+\beta))$ and $\psi(\alpha)=\eta(g'(\alpha))$ and then applying
Theorem \ref{inv}, we deduce that there exist an integer $N_{0}'$ and a constant 
$\sigma_{2}>0$ such that if $N\geq N_{0}'$, then the sequence $(g'(m+ni))_{(m,n)\in[\tilde{N}]\times[\tilde{N}]}$ 
is not totally $\sigma_{2}$-equidistributed in $X$. Hence in the rest of the proof, we can take $\beta=0$ 
and $g_{0}=id_{G}$.

\textbf{Step 3: Non-equidistribution on $X\times X$.}
Combining (\ref{B3}) with Lemma \ref{katai}, there exist a positive integer $K$, primes $p=p_{1}+p_{2}i,q=q_{1}+q_{2}i\in\mathbb{P}[i]$ with $\mathcal{N}(p)<\mathcal{N}(q)<K$, and a positive constant $\kappa_{3}$ such that
\begin{equation}\label{B00}
  \begin{split}
   \frac{1}{N^{2}}\Bigl\vert\sum_{\alpha\in R_{\tilde{N}}/p\cap R_{\tilde{N}}/q}\bold{1}_{P}(p\alpha)\bold{1}_{P}(q\alpha)\Phi(g'(p\alpha)\cdot e_{X})\overline{\Phi}
   (g'(q\alpha)\cdot e_{X})\Bigr\vert>\kappa_{3}.
  \end{split}
  \end{equation}
Since $p,q$ belong to a finite set whose cardinality depends only on $\kappa$, we may consider these numbers as fixed. Let $L$ be a sufficiently large integer depending only on $X$ and $\kappa$ to be chosen later. Let $N>L^{2}$. By (\ref{B00}) and a similar argument to that of Lemma 3.1 in ~\cite{er2}, for each $\gamma=r_{1}+r_{2}i$ with $r_{1},r_{2}\in[L]$, there exists $\beta_{\gamma}\in R_{\tilde{N}}$ such that
\begin{equation}\label{B001}
  \begin{split}
   \frac{L^{2}}{N}\Bigl\vert\sum_{n\in[N/L^{2}],\beta_{\gamma}+n\gamma\in R_{\tilde{N}}}\bold{1}_{P_{\gamma}}(n)\Phi(g'(p(\beta_{\gamma}+n\gamma))\cdot e_{X})\overline{\Phi}
   (g'(q(\beta_{\gamma}+n\gamma))\cdot e_{X})\Bigr\vert>\kappa_{3}/2
  \end{split}
  \end{equation}
for some arithmetic progression $P_{\gamma}$. Let $f_{1}(\gamma)=g_{1,1}^{r_{1}p_{1}-r_{2}p_{2}}g_{1,2}^{r_{1}p_{2}+r_{2}p_{1}},
f_{2}(\gamma)=g_{1,1}^{r_{1}q_{1}-r_{2}q_{2}}g_{1,2}^{r_{1}q_{2}+r_{2}q_{1}}$ be maps from $[L]^{2}$ to $G$. Then by Proposition \ref{last} (replacing $\bold{a}$ and $\bold{b}$ with $f_{1}(\gamma)$ and $f_{2}(\gamma)$), $(f_{1}(\gamma),f_{2}(\gamma))$ satisfies one of the two claims (with $N$ replaced by $N/L^{2}$). So there exist $D=D(X,\kappa)>0, C(L)>1$ and a subset $W$ of $[L]^{2}$ such that $\vert W\vert\geq L^{2}/4$, and one of the following holds:



  (i) For all $\gamma\in W$, there exist horizontal characters $\eta_{1,\gamma},\eta_{2,\gamma}$ such that
$0<\Vert\eta_{1,\gamma}\Vert,\Vert\eta_{2,\gamma}\Vert\leq D$ and $\Vert\eta_{1,\gamma}\circ h_{1,\{\gamma\}}\Vert_{C^{\infty}[N]},\Vert\eta_{1,\gamma}\circ h_{2,\{\gamma\}}\Vert_{C^{\infty}[N]}\leq C(L)D$, where $h_{1,\{\gamma\}}(n)=f_{1}({\gamma})^{n},h_{2,\{\gamma\}}(n)=f_{2}({\gamma})^{n}$;

  (ii) For all $\gamma\in W$, there exists a matrix $M(\gamma)\in \Lambda(B_{0}^{G})$ of height at most $D$ such that $f_{1}({\gamma})^{\bullet}B_{0}^{G}M(\gamma)=_{C(L)D}f_{2}({\gamma})^{\bullet}B_{0}^{G}$. 

Here the notation $A=_{D}B$ means that $A$ is at most $\frac{D}{N}$-away from $B$, and we use this notation throughout the proof.

Since the number of choices of $\eta_{1},\eta_{2}$ and $M$ is bounded by a constant depending only on $X$ and $\kappa$,
if $L$ is sufficiently large, there exist $\epsilon=\epsilon(X,\kappa)>0$ and a subset $V$ of $W$ such that $\vert V\vert>\epsilon L^{2}$ and for all
 $\gamma\in W$, the corresponding $\eta_{1,\gamma},\eta_{2,\gamma},M(\gamma)$, depending on which of the above 
situations occurs, are the the same. We denote this vector or matrix by $\eta_{1},\eta_{2}$ or $M$ depending on which of the above two situations occurs.
By Lemma 3.2 in ~\cite{er2}, the vectors in $V$ spans $\mathbb{Q}^{2}$.

Write $D_{1}=C(L)D$, which depends only $X$ and $\kappa$ (since $L$ depends only on $X$ and $\kappa$). Suppose $\widehat{g_{1,1}}=\bold{a}, \widehat{g_{1,2}}=\bold{b}$, and
$\bold{a}^{\bullet},\bold{b}^{\bullet}$ are the first $s'$ coordinates of $g_{1,1}$ and $g_{1,2}$, respectively.

\textbf{Case (i).} Now we have that $\Vert\eta_{1}\circ h_{1,\{1\}}\Vert,\Vert\eta_{1}\circ h_{1,\{i\}}\Vert\leq D_{1}$. Suppose that $\eta_{1}(\bold{x})=\bold{k}\cdot\widehat{\bold{x}}, 0<\Vert \bold{k}\Vert\leq D_{1}$. Then
\begin{equation}\nonumber
  \begin{split}
  &\Vert p_{1}\bold{k}\cdot\bold{a}+p_{2}\bold{k}\cdot\bold{b}\Vert_{\mathbb{R}/\mathbb{Z}}\leq D_{1}/N;
    \\& \Vert -p_{2}\bold{k}\cdot\bold{a}+p_{1}\bold{k}\cdot\bold{b}\Vert_{\mathbb{R}/\mathbb{Z}}\leq D_{1}/N.
  \end{split}
\end{equation}
This implies $\Vert \Delta\bold{k}\cdot\bold{a}\Vert_{\mathbb{R}/\mathbb{Z}}, \Vert \Delta\bold{k}\cdot\bold{b}\Vert_{\mathbb{R}/\mathbb{Z}}\leq D_{2}/N$, where $\Delta=p_{1}^{2}+p_{2}^{2}\neq 0$. Then by Theorem \ref{inv}, $(g(m,n))_{(m,n)\in[\tilde{N}]\times[\tilde{N}]}$ is not totally $\kappa_{4}$-equidistributed, a contradiction.

\textbf{Case (ii).} Now we have that $f_{1}(1)^{\bullet}B_{0}^{G}M=_{D_{1}}f_{2}(1)^{\bullet}B_{0}^{G},f_{1}(i)^{\bullet}B_{0}^{G}M=_{D_{1}}f_{2}(i)^{\bullet}B_{0}^{G}$ (recall that $A=_{D}B$ means that $A$ is at most $\frac{D}{N}$-away from $B$). This is equivalent to saying that
\begin{equation}\label{rep}
\begin{split}
  WM=_{D_{1}}RW,
\end{split}
\end{equation}
where
\begin{equation}\nonumber
W=\binom{\bold{a}^{\bullet}}{\bold{b}^{\bullet}}B_{0}^{G}, R=P^{-1}Q,
P=\begin{vmatrix}

p_{1} &  p_{2}\\

-p_{2} & p_{1}\\
\end{vmatrix},
Q=\begin{vmatrix}

q_{1} &  q_{2}\\

-q_{2} & q_{1}\\
\end{vmatrix}.
\end{equation}
Let $f$ and $g$ be the minimal polynomials of the matrices $M$ and $R$, respectively, i.e.
the integer polynomials with leading coefficient 1 and with the smallest
degree such that $f(M)=0$ and $g(R)=0$. Since $M$ and $R$ are integer matrices of height at most $D_{1}$, $f$ and $g$ are polynomials
with coefficients of height at most $D_{2}$. Since
\begin{equation}\nonumber
R=\begin{vmatrix}

x &  y\\

-y & x\\
\end{vmatrix}
\end{equation}
for some rational numbers $x$ and $y$ not both 0, we deduce that $\deg g=2$.

If $g(M)\neq 0$, then (\ref{rep}) implies that $0=g(R)W=_{D_{3}}Wg(M)$. Since $g(M)\neq 0$, there exists at least one column of $g(M)$ which is not 0.
So there exists
$\bold{v}\in\mathbb{Z}^{s'},0<\Vert\bold{v}\Vert\leq D_{4}$ such that $\Vert\bold{v}\cdot\bold{a}^{\bullet} B_{0}^{G}\Vert,\Vert\bold{v}\cdot\bold{b}^{\bullet} B_{0}^{G}\Vert\leq\frac{D_{4}}{N}$. By Theorem \ref{inv} and the fact that $B_{0}^{G}$ is invertible, $(g(m,n))_{(m,n)\in[\tilde{N}]\times[\tilde{N}]}$ is not totally $\kappa_{4}$-equidistributed, a contradiction.

If $g(M)=0$ but $f(R)\neq 0$, then (\ref{rep}) implies that $0=Wf(M)=_{D_{3}}f(R)W$. By the minimality of $f$, we have that $f$ divides $g$. Since $\deg g=2$, we deduce that $\deg f\leq 1$. This means that $M$ is diagonal. Thus $\lambda f_{1}(1)^{\bullet}B_{0}^{G}=_{D_{1}}f_{2}(1)^{\bullet}B_{0}^{G},\lambda f_{1}(i)^{\bullet}B_{0}^{G}=_{D_{1}}f_{2}(i)^{\bullet}B_{0}^{G}$ for some $\lambda\in\mathbb{Z}, \vert\lambda\vert\leq D$. This implies that
\begin{equation}\nonumber
  \begin{split}
  &\lambda p_{1}\bold{a}^{\bullet} B_{0}^{G}+\lambda p_{2}\bold{b}^{\bullet} B_{0}^{G}=_{D_{1}}q_{1}\bold{a}^{\bullet} B_{0}^{G}+q_{2}\bold{b}^{\bullet} B_{0}^{G};
    \\& -\lambda p_{2}\bold{a}^{\bullet} B_{0}^{G}+\lambda p_{1}\bold{b}^{\bullet} B_{0}^{G}=_{D_{1}}-q_{2}\bold{a}^{\bullet} B_{0}^{G}+q_{1}\bold{b}^{\bullet} B_{0}^{G}.
  \end{split}
\end{equation}
Thus $\bold{a}^{\bullet} B_{0}^{G}=_{D_{2}}\bold{b}^{\bullet} B_{0}^{G}=_{D_{2}}\bold{0}$. Since $G$ is not abelian, there exists at least one row $\bold{v}$ of $B_{0}^{G}$ such that $\bold{v}\neq\bold{0}$.
Then $\bold{v}\cdot\bold{a}^{\bullet}=_{D_{2}}\bold{v}\cdot\bold{b}^{\bullet}=_{D_{2}}0$. So $(g(m,n))_{(m,n)\in[\tilde{N}]\times[\tilde{N}]}$ is not totally $\kappa_{4}$-equidistributed, a contradiction.

If $f(R)=0$ and $g(M)=0$, then $f=g$. Since
$\deg g=2,$ we may assume that $f(x)=g(x)=x^{2}+c_{1}x+c_{0}, c_{0},c_{1}\in\mathbb{Z}$ and let $\mu_{1},\mu_{2}$
be its roots. Since $R$ has no real eigenvalue, $\mu_{1}$ and $\mu_{2}$ are conjugate complex numbers. Since $M^{2}+c_{1}M+c_{0}I=0$, the eigenvalues of $M$ are $\mu_{1}$ and $\mu_{2}$, and from the fact that $c_{0},c_{1}\in\mathbb{Z}$ and $\mu_{1}, \mu_{2}$ are not real numbers, we can easily
deduce that the Jordan normal form $J$ of $M$ must be a diagonal matrix with each entry on the diagonal either $\mu_{1}$ or $\mu_{2}$. So
there exists an $m\times m$ invertible complex-valued matrix $S$ such that
\begin{equation}\nonumber
\begin{split}
M=SJS^{-1}.
\end{split}
\end{equation}
Since $M\in\Lambda(B_{0}^{G})$, we deduce that
\begin{equation}\label{zxc}
\begin{split}
J(S^{T}B_{0}^{G}S)J=S^{T}B_{0}^{G}S.
\end{split}
\end{equation}
Since $\mu_{1}, \mu_{2}$ are not real numbers, $\mu_{1}^{2}\neq 1$ and $\mu_{2}^{2}\neq 1$. Since we also have that $\mu_{1}\mu_{2}=\det R=\det Q/\det P\neq 1$, we can deduce from (\ref{zxc}) and the fact that $J$ is diagonal that $S^{T}B_{0}^{G}S=0$, i.e., $B_{0}^{G}=0$. In other words, $G$ is abelian, a contradiction.

