\label{1p}
  Let $N\in\mathbb{N}$. For every function $a\colon R_{\tilde{N}}\rightarrow\mathbb{C}$ and all arithmetic progressions $P_{1}, P_{2}\subset[\tilde{N}]$, we have that
  \begin{equation}\nonumber
    \begin{split}
      \Bigl\vert\mathbb{E}_{\alpha\in R_{\tilde{N}}}\bold{1}_{P}(\alpha)a(\alpha)\Bigr\vert\leq c_{1}\Vert a\Vert_{U^{2}(R_{\tilde{N}})}
    \end{split}
  \end{equation}
  for some universal constant $c_{1}$, where $P=\{a+bi\in R_{\tilde{N}}\colon a\in P_{1}, b\in P_{2}\}$.

Since $\tilde{N}$ is a prime, the norm $\Vert a\Vert_{U^{2}(\alpha)}$ is invariant under any change of variables of the form $m+ni\rightarrow (am+c)+(bn+d)i$, where $a,b,c,d\in\mathbb{N}$ and $\tilde{N}\nmid a, \tilde{N}\nmid b$. So we may assume without loss of generality that $P_{i}$ is an interval $\{1,\dots,d_{i}\}$, for $i=1,2$. A direct computation shows that
  \begin{equation}\nonumber
  \begin{split}
   \vert\widehat{\bold{1}_{P}}(x+yi)\vert\leq\frac{4}{\tilde{N}^{2}}\Vert x/\tilde{N}\Vert\cdot\Vert y/\tilde{N}\Vert=\frac{4}{\min\{x,\tilde{N}-x\}\cdot\min\{y,\tilde{N}-y\}}
  \end{split}
\end{equation}
for all $x+yi\in R_{\tilde{N}}$. Thus
    \begin{equation}\nonumber
  \begin{split}
   \Bigl\Vert\widehat{\bold{1}_{P}}(x+yi)\Bigr\Vert_{\ell^{4/3}(R_{\tilde{N}})}\leq c_{1}
  \end{split}
\end{equation}
for some universal constant $c_{1}$. Then by Parseval's identity, H\"{o}lder's inequality, and identity (\ref{F}), we deduce that
  \begin{equation}\nonumber
  \begin{split}
    \Bigl\vert\mathbb{E}_{\alpha\in R_{\tilde{N}}}\bold{1}_{P}(\alpha)a(\alpha)\Bigr\vert
    =\Bigl\vert\sum_{\alpha\in R_{\tilde{N}}}\widehat{\bold{1}_{P}}(\alpha)\widehat{a}(\alpha)\Bigr\vert
    \leq c_{1}\Bigl(\sum_{\xi\in R_{\tilde{N}}}\vert \widehat{a}(\xi)\vert^{4}\Bigr)^{1/4}
    \leq c_{1}\Vert a\Vert_{U^{2}(R_{\tilde{N}})}.
  \end{split}
\end{equation}

\label{nU3w}(Weak $U^{3}$ decomposition theorem).
  For every $\theta_{0},\epsilon>0$, there exist positive integers $Q=Q(\epsilon,\theta_{0}),R=R(\epsilon,\theta_{0}), N_{0}=(\epsilon,\theta_{0})$ and $0<\theta<\theta_{0}$ such that for every $N\geq N_{0}$ and every $\chi\in\mathcal{M}_{\mathbb{Z}[i]}$, the function $\chi_{N}$ can be written as
  \begin{equation}\nonumber
   \begin{split}
     \chi_{N}(\alpha)=\chi_{N,s}(\alpha)+\chi_{N,u}(\alpha),
   \end{split}
  \end{equation}
where

  (i) $\chi_{N,s}=\chi_{N}*\phi_{N,\theta}$, where $\phi_{N,\theta}$ is the kernel of $R_{\tilde{N}}$ defined in Theorem \ref{nU2}
  which is independent of $\chi$, and the convolution product is defined on $R_{\tilde{N}}$;

  (ii)$\vert\chi_{N,s}(\alpha+Q)-\chi_{N,s}(\alpha)\vert, \vert\chi_{N,s}(\alpha+Qi)-\chi_{N,s}(\alpha)\vert\leq\frac{R}{N}$ for every $\alpha\in R_{\tilde{N}}$;

  (iii)$\Vert\chi_{N,u}\Vert_{U^{3}(R_{\tilde{N}})}\leq\epsilon$.

